window.__WB_TEXTBOOK__ = [{"id": "purple", "name": "紫书 · 算法竞赛入门经典（第2版）", "author": "刘汝佳", "level": "零基础入门", "repo_url": "https://github.com/sonnycalcr/aoapc-bac2nd", "chapters": [{"cid": "Ch.01", "title": "程序设计入门", "summary": "本章奠定算法竞赛的编码基石，围绕标准输入输出、算术表达式求值、浮点数精度控制与分支逻辑展开。核心方法论在于理解计算机底层数据类型范围（如 $32$ 位整数上限 $2^{31}-1$）与 IEEE 754 浮点误差来源，培养使用数学等价变换替代暴力试探的思维习惯，并建立边界条件（零值、负数、极值）的完备性检查意识，为后续复杂算法实现消除低级 Bug。", "template_cpp": "#include <iostream>\n#include <iomanip>\n#include <cmath>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    double r, h;\n    if (cin >> r >> h) {\n        const double pi = acos(-1.0);\n        double area = 2.0 * pi * r * r + 2.0 * pi * r * h;\n        cout << fixed << setprecision(3) << area << '\\n';\n    }\n    return 0;\n}", "pitfalls": "整数除法截断（如 $1/2=0$）；`double` 比较未用 `eps`（$10^{-9}$）；`scanf` 与 `cin` 混用导致流同步错乱；忽略多组数据结尾 EOF 处理。", "workbench_tags": ["模拟", "数学", "复杂度"], "problems": [{"oj": "UVa", "pid": "10055", "title": "Hashmat the Brave Warrior", "diff": "入门", "hint": "输入可能达 $2^{32}$，需使用 `long long` 计算 $|a-b|$。"}, {"oj": "UVa", "pid": "10071", "title": "Back to High School Physics", "diff": "入门", "hint": "匀加速直线运动位移公式化简后直接输出 $2vt$。"}, {"oj": "UVa", "pid": "11172", "title": "Relational Operator", "diff": "入门", "hint": "读取 $t$ 组整数，直接比较大小输出对应关系符号。"}]}, {"cid": "Ch.02", "title": "循环结构程序设计", "summary": "本章聚焦 `for`、`while`、`do-while` 循环控制流与高精度迭代技巧，核心思想是将重复计算抽象为状态转移与循环不变量维护。通过阶乘累加取模、近似级数收敛、数位拆解与重定向调试等经典范式，训练在 $O(n)$ 与 $O(n^2)$ 规模下的时间复杂度直觉，强调中间变量溢出预防与循环终止条件的严格数学验证。", "template_cpp": "#include <iostream>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n, kase = 0;\n    while (cin >> n && n > 0) {\n        long long x, mn = (1LL << 60), mx = -(1LL << 60), sum = 0;\n        for (int i = 0; i < n; ++i) {\n            cin >> x;\n            mn = min(mn, x);\n            mx = max(mx, x);\n            sum += x;\n        }\n        cout << \"Case \" << ++kase << \": \" << mn << ' ' << mx << ' ' << sum << '\\n';\n    }\n    return 0;\n}", "pitfalls": "多组测试数据未重置累加器或极值变量；浮点循环变量（如 `for(double x=0; x!=1; x+=0.1)`）因精度误差死循环；输出格式缺少 Case 间空行或行末多余空格。", "workbench_tags": ["模拟", "枚举"], "problems": [{"oj": "UVa", "pid": "1225", "title": "Digit Counting", "diff": "入门", "hint": "枚举 $1$ 到 $N$ 的每个整数并逐位取模统计 $0\\sim 9$ 频次。"}, {"oj": "UVa", "pid": "1583", "title": "Digit Generator", "diff": "入门", "hint": "预处理 $1\\sim 100000$ 的生成元映射表即可 $O(1)$ 查询。"}, {"oj": "UVa", "pid": "1584", "title": "Circular Sequence", "diff": "入门", "hint": "枚举所有旋转起点，按字典序比较长度为 $n$ 的环状串。"}, {"oj": "UVa", "pid": "272", "title": "TEX Quotes", "diff": "入门", "hint": "维护布尔状态 `left` 交替替换双引号为 `` 和 ''。"}]}, {"cid": "Ch.03", "title": "数组和字符串", "summary": "本章系统讲解一维与二维静态数组、字符数组及字符频率统计，核心方法论是利用空间换时间（如查表法、常量映射表与前缀统计）消除繁琐的条件分支。重点涵盖蛇形填数、回文与镜像串判定、竖式模拟等典型问题，强调数组越界防御、较大数组应声明在全局区避免栈溢出，以及字符串结束符 `'\\0'` 与换行符 `\\r\\n` 的跨平台兼容处理。", "template_cpp": "#include <iostream>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    string s;\n    while (cin >> s) {\n        string rev = s;\n        reverse(rev.begin(), rev.end());\n        bool is_pal = (s == rev);\n        cout << s << (is_pal ? \" -- is a palindrome.\" : \" -- is not a palindrome.\") << '\\n';\n    }\n    return 0;\n}", "pitfalls": "局部大数组导致栈溢出（Stack Overflow）；`gets` 已被 C++11/17 移除且易越界，混用 `cin >>` 与 `getline` 时未吸收残留换行符；下标从 $0$ 还是 $1$ 混淆。", "workbench_tags": ["字符串", "数据结构", "模拟"], "problems": [{"oj": "UVa", "pid": "401", "title": "Palindromes", "diff": "入门", "hint": "构建字符镜像映射表，同时双指针检查回文与镜像性质。"}, {"oj": "UVa", "pid": "340", "title": "Master-Mind Hints", "diff": "入门", "hint": "先统计位置数字均匹配数 $A$，再对 $1\\sim 9$ 统计出现次数最小值之和减去 $A$ 得 $B$。"}, {"oj": "UVa", "pid": "1585", "title": "Score", "diff": "入门", "hint": "线性扫描维护连续 `O` 的长度 `cnt`，遇到 `X` 清零即可。"}, {"oj": "UVa", "pid": "455", "title": "Periodic Strings", "diff": "普及", "hint": "从小到大枚举整除串长 $n$ 的周期 $p$，验证 $s[i]=s[i\\%p]$。"}]}, {"cid": "Ch.04", "title": "函数和递归", "summary": "本章引入模块化编程思想，剖析函数值传递与引用/指针传递的内存机制、结构体封装以及递归调用栈模型。核心在于将复杂模拟拆解为职责单一的子函数，并理解递归的终止条件与状态收敛性，同时掌握结构体排序与自定义比较规则，为后续分治、搜索和动态规划建立清晰的抽象边界。", "template_cpp": "#include <iostream>\n#include <vector>\nusing namespace std;\n\nint gcd(int a, int b) {\n    return b == 0 ? a : gcd(b, a % b);\n}\n\nlong long comb(int n, int m) {\n    if (m > n - m) m = n - m;\n    long long ans = 1;\n    for (int i = 1; i <= m; ++i) {\n        ans = ans * (n - m + i) / i;\n    }\n    return ans;\n}\n\nint main() {\n    int n, m;\n    if (cin >> n >> m) {\n        cout << gcd(n, m) << ' ' << comb(n, m) << '\\n';\n    }\n    return 0;\n}", "pitfalls": "递归深度过大引发栈溢出；组合数计算先乘后除仍可能溢出 `long long`（应边乘边约分）；忘记在多组数据中初始化结构体数组。", "workbench_tags": ["模拟", "数学", "搜索"], "problems": [{"oj": "UVa", "pid": "133", "title": "The Dole Queue", "diff": "入门", "hint": "用数组标记出队状态，编写步进函数按顺逆时针跳过已出队元素。"}, {"oj": "UVa", "pid": "489", "title": "Hangman Judge", "diff": "入门", "hint": "用集合或布尔数组记录已猜字符，避免重复猜错同一字母扣命。"}, {"oj": "UVa", "pid": "213", "title": "Message Decoding", "diff": "普及", "hint": "按长度 $len$ 与二进制编码值映射二维字符表，注意跳过换行符读取比特流。"}, {"oj": "UVa", "pid": "512", "title": "Spreadsheet Tracking", "diff": "普及", "hint": "不必真实维护网格，只需记录操作序列并对查询坐标逆向或正向追踪位置变化。"}]}, {"cid": "Ch.05", "title": "C++与STL入门", "summary": "本章是迈向现代竞赛编程的关键跃迁，系统介绍 `vector`、`set`、`map`、`stack`、`queue`、`priority_queue` 与 `algorithm` 通用算法。核心方法论是通过标准容器实现 $O(\\log n)$ 级别的去重、映射、动态排序与堆维护，并借助 `stringstream` 与结构体运算符重载大幅缩短代码量、提升可读性与鲁棒性。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <map>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    map<int, int> cnt;\n    for (int &x : a) {\n        cin >> x;\n        cnt[x]++;\n    }\n    sort(a.begin(), a.end());\n    a.erase(unique(a.begin(), a.end()), a.end());\n    for (int x : a) cout << x << ':' << cnt[x] << '\\n';\n    return 0;\n}", "pitfalls": "自定义比较器未满足严格弱序（如 `a <= b` 返回 `true` 导致段错误）；`map` 访问不存在的键会自动插入默认值；`vector::size()` 为无符号类型，直接减 $1$ 在空容器时会下溢为极大正数。", "workbench_tags": ["STL", "数据结构", "排序与二分"], "problems": [{"oj": "UVa", "pid": "10474", "title": "Where is the Marble?", "diff": "入门", "hint": "排序后使用 `lower_bound` 定位首个等于查询值的位置。"}, {"oj": "UVa", "pid": "10815", "title": "Andy's First Dictionary", "diff": "入门", "hint": "将非字母字符替换为空格后用 `stringstream` 分词，全部转小写存入 `set`。"}, {"oj": "UVa", "pid": "156", "title": "Ananagrams", "diff": "入门", "hint": "将每个单词转小写并排序字母作为标准化键值存入 `map` 统计频次。"}, {"oj": "UVa", "pid": "136", "title": "Ugly Numbers", "diff": "入门", "hint": "用小根堆 `priority_queue` 配合 `set` 去重，依次取出第 $1500$ 个丑数。"}, {"oj": "UVa", "pid": "12096", "title": "The SetStack Computer", "diff": "普及", "hint": "为每个不同集合分配唯一整数 ID（ID 缓存），栈中只存 ID 以加速集合嵌套运算。"}]}, {"cid": "Ch.06", "title": "数据结构基础", "summary": "本章深入链式结构、二叉树与图的基础表示，核心思想是用静态数组模拟指针以兼顾内存安全与访问效率，并通过 DFS 递归建树、BFS 层次遍历与拓扑排序解决树图连通性问题。同时引入并查集与队列模拟的经典应用，训练将复杂物理过程抽象为状态图节点与边转移的能力。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> g(n + 1);\n    vector<int> indeg(n + 1, 0);\n    for (int i = 0, u, v; i < m; ++i) {\n        cin >> u >> v;\n        g[u].push_back(v);\n        indeg[v]++;\n    }\n    queue<int> q;\n    for (int i = 1; i <= n; ++i) if (!indeg[i]) q.push(i);\n    while (!q.empty()) {\n        int u = q.front(); q.pop();\n        cout << u << ' ';\n        for (int v : g[u]) if (--indeg[v] == 0) q.push(v);\n    }\n    return 0;\n}", "pitfalls": "BFS 入队时未立即标记 `vis` 导致同一节点多次入队内存爆炸；拓扑排序未检查已访问节点数是否等于 $n$ 而漏判有向环；二叉树数组大小未按完全二叉树最坏深度开够。", "workbench_tags": ["数据结构", "树形结构", "图论", "搜索"], "problems": [{"oj": "UVa", "pid": "514", "title": "Rails", "diff": "入门", "hint": "用栈模拟车站中转过程，贪心匹配目标出栈序列的队头元素。"}, {"oj": "UVa", "pid": "11988", "title": "Broken Keyboard", "diff": "普及", "hint": "使用链表（或静态数组 `next[]`）在 $O(1)$ 时间内将光标切换至行首或行尾。"}, {"oj": "UVa", "pid": "679", "title": "Dropping Balls", "diff": "普及", "hint": "根据小球编号的奇偶性直接推算每层向左还是向右走，复杂度降至 $O(D)$。"}, {"oj": "UVa", "pid": "572", "title": "Oil Deposits", "diff": "入门", "hint": "对二维网格中每个未访问的 `@` 启动八连通 DFS/BFS 洪水填充计数。"}, {"oj": "UVa", "pid": "10305", "title": "Ordering Tasks", "diff": "入门", "hint": "Kahn 算法或 DFS 逆后序求解有向无环图的拓扑排序。"}]}, {"cid": "Ch.07", "title": "暴力求解法", "summary": "本章系统构建穷举搜索与状态空间探索的方法论，涵盖子集生成、全排列枚举、回溯剪枝、BFS 最短路状态转移以及迭代加深搜索（IDDFS）与 $A^*$ 启发式剪枝。核心思想是在解空间树上通过可行性剪枝、最优性剪枝与对称性破除大幅压缩搜索树分支因子，在有限时限内求出精确最优解。", "template_cpp": "#include <iostream>\n#include <vector>\nusing namespace std;\n\nint n, ans = 0;\nbool col[20], diag1[40], diag2[40];\n\nvoid dfs(int r) {\n    if (r == n) {\n        ans++;\n        return;\n    }\n    for (int c = 0; c < n; ++c) {\n        if (col[c] || diag1[r + c] || diag2[r - c + n]) continue;\n        col[c] = diag1[r + c] = diag2[r - c + n] = true;\n        dfs(r + 1);\n        col[c] = diag1[r + c] = diag2[r - c + n] = false;\n    }\n}\n\nint main() {\n    if (cin >> n) { dfs(0); cout << ans << '\\n'; }\n    return 0;\n}", "pitfalls": "回溯返回时未恢复全局状态现场；BFS 隐式图搜索未用哈希表或康托展开判重导致死循环；迭代加深（IDA*）估价函数 $h(x)$ 超过了真实剩余代价而失去最优性保证。", "workbench_tags": ["搜索", "枚举"], "problems": [{"oj": "UVa", "pid": "725", "title": "Division", "diff": "入门", "hint": "只枚举分母 $fghij$（$1234\\sim 98765$），乘 $n$ 得分子后验证 $10$ 个数字互异。"}, {"oj": "UVa", "pid": "524", "title": "Prime Ring Problem", "diff": "入门", "hint": "固定首位为 $1$，DFS 回溯枚举排列并实时检查相邻之和是否为素数。"}, {"oj": "UVa", "pid": "10603", "title": "Fill", "diff": "普及", "hint": "将三杯水量视作状态，使用优先队列（Dijkstra）以倒水总量为边权搜索最小代价。"}, {"oj": "UVa", "pid": "12558", "title": "Egyptian Fractions (HARD version)", "diff": "提高", "hint": "采用 IDA* 迭代加深搜索，按分母递增枚举并利用上下界剪枝避开禁用分母。"}]}, {"cid": "Ch.08", "title": "高效算法设计", "summary": "本章转向时间复杂度优化，核心方法论包括分治递归、前缀和、滑动窗口、二分答案（将最优化问题转化为判定问题）以及排序后的贪心策略与区间调度。通过分析问题单调性与子问题独立性，将 $O(n^2)$ 朴素解法降至 $O(n \\log n)$ 甚至 $O(n)$，培养通过数学直觉与反证法证明贪心正确性的严谨习惯。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nbool check(const vector<int>& a, int m, long long limit) {\n    long long cur = 0;\n    int cnt = 1;\n    for (int x : a) {\n        if (x > limit) return false;\n        if (cur + x > limit) { cnt++; cur = x; }\n        else cur += x;\n    }\n    return cnt <= m;\n}\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<int> a(n);\n    for (int &x : a) cin >> x;\n    long long l = 1, r = 1e14, ans = r;\n    while (l <= r) {\n        long long mid = l + (r - l) / 2;\n        if (check(a, m, mid)) { ans = mid; r = mid - 1; }\n        else l = mid + 1;\n    }\n    cout << ans << '\\n';\n    return 0;\n}", "pitfalls": "二分边界 `l <= r` 与 `l < r` 更新不匹配导致死循环；`mid = (l + r) / 2` 在负数或大数时溢出或向零取整错误；贪心排序关键字选择错误（如区间覆盖按左端点还是右端点排序）。", "workbench_tags": ["排序与二分", "贪心", "分治"], "problems": [{"oj": "UVa", "pid": "1152", "title": "4 Values whose Sum is 0", "diff": "普及", "hint": "折半枚举：$O(n^2)$ 预处理 $A+B$ 存入哈希表或排序数组，再枚举 $-(C+D)$ 查找。"}, {"oj": "UVa", "pid": "11572", "title": "Unique Snowflakes", "diff": "普及", "hint": "双指针滑动窗口配合哈希表/集合维护极长无重复元素子段。"}, {"oj": "UVa", "pid": "11134", "title": "Fabled Rooks", "diff": "提高", "hint": "行与列坐标相互独立，分别按区间右端点贪心分配最小可用坐标。"}, {"oj": "UVa", "pid": "1605", "title": "Building for UN", "diff": "普及", "hint": "构造两层正交网格：第一层每行同国，第二层每列同国，保证任意两国相邻。"}]}, {"cid": "Ch.09", "title": "动态规划初步", "summary": "本章系统建立动态规划（DP）的核心框架：无后效性、最优子结构与状态转移方程。内容覆盖 DAG 最长路模型、0-1 背包与完全背包、区间 DP、树形 DP 以及状压 DP 的初步应用。强调在“记忆化搜索”与“递推填表”之间自由切换，并学会通过滚动数组优化空间复杂度以及通过记录决策点还原最优方案路径。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n, W;\n    cin >> n >> W;\n    vector<int> dp(W + 1, 0);\n    for (int i = 0; i < n; ++i) {\n        int w, v;\n        cin >> w >> v;\n        for (int j = W; j >= w; --j) {\n            dp[j] = max(dp[j], dp[j - w] + v);\n        }\n    }\n    cout << dp[W] << '\\n';\n    return 0;\n}", "pitfalls": "0-1 背包内层循环写成正序导致同一物品被重复选取；区间 DP 外层循环枚举左端点而非区间长度导致依赖的子区间尚未计算；DP 初值未区分“恰好装满”（设为 $-\\infty$）与“至多装满”（设为 $0$）。", "workbench_tags": ["DP", "树上问题"], "problems": [{"oj": "UVa", "pid": "116", "title": "Unidirectional TSP", "diff": "普及", "hint": "从最后一列向第一列倒推 DP，以便同步求得字典序最小的路径。"}, {"oj": "UVa", "pid": "437", "title": "The Tower of Babylon", "diff": "普及", "hint": "每种立方体拆成 3 种固定底面朝向，按底面积排序后求 DAG 上的 LIS。"}, {"oj": "UVa", "pid": "10003", "title": "Cutting Sticks", "diff": "普及", "hint": "经典区间 DP：$dp[i][j] = \\min_{i<k<j}(dp[i][k]+dp[k][j]) + c[j]-c[i]$。"}, {"oj": "UVa", "pid": "1220", "title": "Party at Hali-Bula", "diff": "提高", "hint": "树形最大独立集 DP，同时额外维护布尔标志判断最优解是否唯一。"}]}, {"cid": "Ch.10", "title": "数学概念与方法", "summary": "本章汇总竞赛高频数论、组合数学与概率期望工具。核心方法论涵盖埃拉托斯特尼筛法、扩展欧几里得算法（求解线性同余方程与逆元）、二项式系数与容斥原理，以及利用递推关系与线性期望可加性求解期望步数。强调模运算下的乘法防溢出与大数取模规范，使数学推导无缝转化为稳健代码。", "template_cpp": "#include <iostream>\nusing namespace std;\nusing ll = long long;\n\nll exgcd(ll a, ll b, ll &x, ll &y) {\n    if (!b) { x = 1; y = 0; return a; }\n    ll d = exgcd(b, a % b, y, x);\n    y -= (a / b) * x;\n    return d;\n}\n\nll mod_inv(ll a, ll m) {\n    ll x, y;\n    ll d = exgcd(a, m, x, y);\n    if (d != 1) return -1;\n    return (x % m + m) % m;\n}\n\nint main() {\n    ll a, m;\n    if (cin >> a >> m) cout << mod_inv(a, m) << '\\n';\n    return 0;\n}", "pitfalls": "负数取模结果仍为负（需 `(x % m + m) % m`）；费马小定理求逆元要求模数为素数且 $\\gcd(a, p)=1$；快速幂底数未先取模导致首次平方即溢出。", "workbench_tags": ["数学"], "problems": [{"oj": "UVa", "pid": "11582", "title": "Colossal Fibonacci Numbers!", "diff": "普及", "hint": "利用皮萨诺周期：模 $n$ 的斐波那契数列周期不超过 $n^2$，暴力找周期后快速幂取模。"}, {"oj": "UVa", "pid": "10791", "title": "Minimum Sum LCM", "diff": "普及", "hint": "将 $N$ 质因数分解为 $\\prod p_i^{e_i}$，各质因子幂次独立成数相加和最小（注意 $1$ 和单质数特判）。"}, {"oj": "UVa", "pid": "12169", "title": "Disgruntled Judge", "diff": "提高", "hint": "枚举参数 $a$，代入两项关系转化为扩展欧几里得方程求解 $b$ 并验证全序列。"}, {"oj": "UVa", "pid": "10288", "title": "Coupons", "diff": "提高", "hint": "经典赠券收集问题，利用期望线性性得总期望 $n \\sum_{k=1}^n \\frac{1}{k}$，用分数通分输出。"}]}, {"cid": "Ch.11", "title": "图论模型与算法", "summary": "本章作为全书收官，构建从现实问题到图论模型的抽象桥梁，系统讲解无根树转有根树、最小生成树（Kruskal）、单源与全源最短路（Dijkstra、Bellman-Ford/SPFA、Floyd）以及最大流与最小费用最大流（Edmonds-Karp / MCMF）。核心思想是识别问题中的容量限制、最短代价与匹配关系，将其精准建模为图上标准算法。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\nusing ll = long long;\nconst ll INF = 1e18;\n\nint main() {\n    int n, m, s;\n    cin >> n >> m >> s;\n    vector<vector<pair<int, int>>> g(n + 1);\n    for (int i = 0, u, v, w; i < m; ++i) {\n        cin >> u >> v >> w;\n        g[u].push_back({v, w});\n    }\n    vector<ll> dist(n + 1, INF);\n    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;\n    dist[s] = 0; pq.push({0, s});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top(); pq.pop();\n        if (d > dist[u]) continue;\n        for (auto [v, w] : g[u]) {\n            if (dist[u] + w < dist[v]) {\n                dist[v] = dist[u] + w;\n                pq.push({dist[v], v});\n            }\n        }\n    }\n    return 0;\n}", "pitfalls": "Dijkstra 堆优化弹出旧状态时忘记 `if (d > dist[u]) continue;` 导致退化超时；存在负权边误用 Dijkstra；网络流建图忘记同时添加容量为 $0$ 的反向边。", "workbench_tags": ["图论", "树上问题"], "problems": [{"oj": "UVa", "pid": "1151", "title": "Buy or Build", "diff": "提高", "hint": "先求原图 MST 保留其 $n-1$ 条边，再二进制枚举购买的套餐集合并重跑 Kruskal。"}, {"oj": "UVa", "pid": "1395", "title": "Slim Span", "diff": "普及", "hint": "按边权排序后枚举最小边作为下界，依次加边做 Kruskal 直到图连通。"}, {"oj": "UVa", "pid": "247", "title": "Calling Circles", "diff": "普及", "hint": "用 Floyd 求出有向图传递闭包，互达的顶点即属于同一个强连通分量。"}, {"oj": "UVa", "pid": "11082", "title": "Matrix Decompressing", "diff": "提高", "hint": "行列和拆为二分图网络流：源点连行、行连列（容量 $19$，先全体减 $1$）、列连汇点。"}]}]}, {"id": "blue", "name": "蓝书 · 算法竞赛进阶指南", "author": "李煜东", "level": "进阶冲金", "repo_url": "https://github.com/lydrainbowcat/tedukuri", "chapters": [{"cid": "0x00", "title": "基本算法（位运算、递推、二分与贪心）", "summary": "本章重塑基础算法的数学严谨性，深入二进制状态压缩与龟速乘/快速幂、分治与递归的规模折半思想、二维前缀和与差分数组的高效区间修改，以及二分答案与实数三分。核心方法论在于发掘问题潜在的单调性与局部交换不变性（邻项交换法证明贪心），将看似杂乱的序列决策规约为可精确求解的模型。", "template_cpp": "#include <iostream>\nusing namespace std;\nusing ll = long long;\n\nll qpow(ll a, ll b, ll mod) {\n    ll res = 1 % mod;\n    a %= mod;\n    while (b) {\n        if (b & 1) res = (__int128)res * a % mod;\n        a = (__int128)a * a % mod;\n        b >>= 1;\n    }\n    return res;\n}\n\nint main() {\n    ll a, b, p;\n    if (cin >> a >> b >> p) cout << qpow(a, b, p) << '\\n';\n    return 0;\n}", "pitfalls": "模数 $p=1$ 时未写 `1 % mod` 导致 $b=0$ 输出 $1$ 而非 $0$；二维差分边界 `x2+1, y2+1` 数组越界；邻项交换贪心比较函数未满足严格弱序。", "workbench_tags": ["位运算", "排序与二分", "贪心", "分治"], "problems": [{"oj": "AcWing", "pid": "89", "title": "a^b", "diff": "入门", "hint": "二进制拆分指数做快速幂，特判 $p=1$。"}, {"oj": "AcWing", "pid": "99", "title": "激光炸弹", "diff": "普及", "hint": "二维前缀和统计边长为 $R$ 的正方形内目标价值最大值，注意目标可重叠与坐标偏移。"}, {"oj": "AcWing", "pid": "102", "title": "最佳牛围栏", "diff": "提高", "hint": "二分平均数 $mid$，将所有数减 $mid$ 后转化为是否存在长度 $\\ge F$ 且和 $\\ge 0$ 的子段。"}, {"oj": "AcWing", "pid": "114", "title": "国王游戏", "diff": "提高", "hint": "邻项交换证明按 $a_i \\cdot b_i$ 升序排列最优，并需高精度乘除法实现。"}]}, {"cid": "0x10", "title": "基本数据结构（单调队列、Hash 与 Trie）", "summary": "本章挖掘线性数据结构的极值维护潜能，重点剖析单调栈与单调队列如何在线性时间内解决“最近更大元素”与滑动窗口最值，字符串哈希与双哈希防冲突技术，KMP 前缀函数与最小表示法，以及 01-Trie 在最大异或对问题中的按位贪心应用。核心思想是及时剔除“绝无可能成为最优解的冗余状态”。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <deque>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n, k;\n    cin >> n >> k;\n    vector<int> a(n);\n    for (int &x : a) cin >> x;\n    deque<int> dq;\n    for (int i = 0; i < n; ++i) {\n        while (!dq.empty() && dq.front() <= i - k) dq.pop_front();\n        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();\n        dq.push_back(i);\n        if (i >= k - 1) cout << a[dq.front()] << ' ';\n    }\n    return 0;\n}", "pitfalls": "单调队列存值而非下标导致无法判断队头是否滑出窗口；字符串哈希使用单一自然溢出模数在针对性数据下被卡冲突；Trie 节点数估算不足导致数组越界。", "workbench_tags": ["数据结构", "字符串"], "problems": [{"oj": "AcWing", "pid": "128", "title": "编辑器", "diff": "普及", "hint": "对顶栈维护光标左右两侧元素，同步维护左侧前缀和与前缀最大值。"}, {"oj": "AcWing", "pid": "135", "title": "最大子序和", "diff": "提高", "hint": "求前缀和后使用单调递增队列维护长度不超过 $M$ 的窗口内最小 $S[j]$。"}, {"oj": "AcWing", "pid": "138", "title": "兔子与兔子", "diff": "普及", "hint": "预处理字符串前缀哈希与 $P$ 的幂次，实现 $O(1)$ 子串相等性判定。"}, {"oj": "AcWing", "pid": "143", "title": "最大异或对", "diff": "提高", "hint": "将所有数按二进制高位到低位插入 01-Trie，查询时优先走相反比特分支。"}]}, {"cid": "0x20", "title": "搜索（剪枝、双向广搜与 IDA*）", "summary": "本章系统化高阶搜索策略，突破朴素 DFS/BFS 的状态空间瓶颈。核心方法论包含树与图的搜索顺序优化（优先分支少的节点）、可行性与最优性剪枝、折半搜索（Meet-in-the-middle）、双端队列 BFS 处理 $0/1$ 边权最短路，以及结合乐观估价函数 $h(x)$ 的 $A^*$ 与迭代加深 $IDA^*$ 算法。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <deque>\nusing namespace std;\n\nvector<int> bfs01(int n, int s, const vector<vector<pair<int, int>>>& g) {\n    vector<int> dist(n + 1, 1e9);\n    deque<int> dq;\n    dist[s] = 0;\n    dq.push_back(s);\n    while (!dq.empty()) {\n        int u = dq.front(); dq.pop_front();\n        for (auto [v, w] : g[u]) {\n            if (dist[u] + w < dist[v]) {\n                dist[v] = dist[u] + w;\n                if (w == 0) dq.push_front(v);\n                else dq.push_back(v);\n            }\n        }\n    }\n    return dist;\n}\n\nint main() { return 0; }", "pitfalls": "折半搜索合并两半结果时忽略单侧不选或双侧均空的边界；$0/1$ BFS 误将未松弛成功的节点入队；数独或木棒拼合问题未跳过同一层中相同的失败长度导致指数级重复搜索。", "workbench_tags": ["搜索", "图论"], "problems": [{"oj": "AcWing", "pid": "167", "title": "木棒", "diff": "提高", "hint": "从大到小枚举总长约数，降序排列木棒；若当前长度拼接失败则跳过所有相同长度木棒。"}, {"oj": "AcWing", "pid": "171", "title": "送礼物", "diff": "提高", "hint": "折半搜索：前一半 DFS 预处理出所有合法重量和并排序去重，后一半搜索时二分匹配。"}, {"oj": "AcWing", "pid": "175", "title": "电路维修", "diff": "提高", "hint": "网格格点建图，顺方向边权为 $0$、旋转 $90^\\circ$ 边权为 $1$，运行双端队列 $0/1$ BFS。"}, {"oj": "AcWing", "pid": "180", "title": "排书", "diff": "提高", "hint": "使用 IDA*，每次操作最多消除 $3$ 个错误后继，因此估价函数设为 $\\lceil \\text{错误后继数}/3 \\rceil$。"}]}, {"cid": "0x30", "title": "数学知识（数论、线性代数与博弈）", "summary": "本章构建高阶竞赛数学核心体系，覆盖线性筛素数与欧拉函数 $\\varphi(n)$、欧拉定理与扩展欧几里得、中国剩余定理（CRT）、矩阵快速幂加速线性递推、高斯消元解线性方程组与异或空间基（线性基），以及组合计数、容斥原理与 SG 函数（Sprague-Grundy 定理）在公平组合博弈中的应用。", "template_cpp": "#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<int> primes;\nvector<bool> is_comp;\nvector<int> phi;\n\nvoid sieve(int n) {\n    is_comp.assign(n + 1, false);\n    phi.assign(n + 1, 0);\n    phi[1] = 1;\n    for (int i = 2; i <= n; ++i) {\n        if (!is_comp[i]) { primes.push_back(i); phi[i] = i - 1; }\n        for (int p : primes) {\n            if (1LL * i * p > n) break;\n            is_comp[i * p] = true;\n            if (i % p == 0) { phi[i * p] = phi[i] * p; break; }\n            phi[i * p] = phi[i] * (p - 1);\n        }\n    }\n}\n\nint main() { sieve(100000); cout << phi[10] << '\\n'; return 0; }", "pitfalls": "高斯消元未选取主元绝对值最大行导致精度崩溃或漏判自由元；线性基求第 $k$ 小异或和前未将基向量化为行最简形；CRT 模数不互质时未改用 exCRT 合并。", "workbench_tags": ["数学", "博弈论"], "problems": [{"oj": "AcWing", "pid": "196", "title": "质数距离", "diff": "提高", "hint": "先筛出 $\\sqrt{R}$ 内的素数，再用它们去筛区间 $[L, R]$ 内的合数。"}, {"oj": "AcWing", "pid": "204", "title": "表达整数的奇怪方式", "diff": "提高", "hint": "扩展中国剩余定理（exCRT）：利用 exgcd 逐个合并两个同余方程。"}, {"oj": "AcWing", "pid": "207", "title": "球形空间产生器", "diff": "提高", "hint": "相邻两球面方程相减消去二次项，化为 $n$ 元一次线性方程组后用高斯消元求解。"}, {"oj": "AcWing", "pid": "219", "title": "剪纸游戏", "diff": "省选", "hint": "公平组合博弈拆分独立子游戏，记忆化计算矩形状态 $(w, h)$ 的 SG 值并求异或和。"}]}, {"cid": "0x40", "title": "数据结构进阶（并查集、树状数组与线段树）", "summary": "本章深入竞赛最核心的动态区间与集合维护工具。内容涵盖带权并查集与扩展域并查集维护传递关系、树状数组（Fenwick Tree）求逆序对与差分区间加、线段树（懒标记区间修改与扫描线求矩形面积并）、分块与莫队离线算法。核心思想是通过分治划分与延迟更新（Lazy Propagation）将修改与查询均控制在 $O(\\log n)$ 级别。", "template_cpp": "#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct BIT {\n    int n;\n    vector<long long> tr;\n    BIT(int n) : n(n), tr(n + 1, 0) {}\n    void add(int x, long long v) {\n        for (; x <= n; x += x & -x) tr[x] += v;\n    }\n    long long query(int x) {\n        long long res = 0;\n        for (; x > 0; x -= x & -x) res += tr[x];\n        return res;\n    }\n};\n\nint main() {\n    BIT bit(10);\n    bit.add(3, 5);\n    cout << bit.query(5) << '\\n';\n    return 0;\n}", "pitfalls": "线段树数组未开 $4n$ 空间导致越界；多懒标记（如区间乘与区间加）`pushdown` 时未先乘后加；树状数组下标出现 $0$ 引发 `x += x & -x` 死循环。", "workbench_tags": ["数据结构", "树形结构"], "problems": [{"oj": "AcWing", "pid": "237", "title": "程序自动分析", "diff": "普及", "hint": "先离散化所有变量，将相等约束用并查集合并，最后检查不等约束是否在同一集合。"}, {"oj": "AcWing", "pid": "243", "title": "一个简单的整数问题2", "diff": "提高", "hint": "线段树懒标记维护区间加与区间和，或用两个树状数组维护二阶差分前缀和。"}, {"oj": "AcWing", "pid": "247", "title": "亚特兰蒂斯", "diff": "省选", "hint": "扫描线算法：对 $y$ 坐标离散化，按 $x$ 从小到大扫描并用线段树维护当前覆盖总长度。"}, {"oj": "AcWing", "pid": "252", "title": "树", "diff": "省选", "hint": "点分治经典题：每次找树的重心分治，统计经过重心的合法路径数并容斥减去同子树重复贡献。"}]}, {"cid": "0x50", "title": "动态规划（状压、树形、计数与斜率优化）", "summary": "本章系统剖析高阶 DP 的状态设计与转移加速。涵盖最长上升子序列、多维背包、区间与环形 DP、树形 DP（换根二次扫描）、状态压缩 DP（轮廓线与子集转移）以及三大经典优化：单调队列优化多重背包、斜率优化（凸包维护决策点）与四边形不等式优化。核心方法论是将高维决策单调性转化为几何凸壳或单调队列查询。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<int> dp(m + 1, 0);\n    for (int i = 0; i < n; ++i) {\n        int v, w, s;\n        cin >> v >> w >> s;\n        for (int k = 1; k <= s; s -= k, k <<= 1) {\n            for (int j = m; j >= k * v; --j)\n                dp[j] = max(dp[j], dp[j - k * v] + k * w);\n        }\n        if (s > 0) {\n            for (int j = m; j >= s * v; --j)\n                dp[j] = max(dp[j], dp[j - s * v] + s * w);\n        }\n    }\n    cout << dp[m] << '\\n';\n    return 0;\n}", "pitfalls": "斜率优化计算斜率时分母可能为 $0$ 或直接用除法引发精度误差（推荐交叉相乘）；状压 DP 位运算优先级低于加减与比较运算符；换根 DP 忘记考虑子树大小贡献方向。", "workbench_tags": ["DP", "树上问题"], "problems": [{"oj": "AcWing", "pid": "272", "title": "最长公共上升子序列", "diff": "提高", "hint": "设计状态 $f[i][j]$ 为 $A[1..i]$ 与以 $B[j]$ 结尾的 LCIS 长度，外层固定 $i$ 时同步维护前缀最大值将转移降至 $O(1)$。"}, {"oj": "AcWing", "pid": "285", "title": "没有上司的舞会", "diff": "普及", "hint": "树形 DP 基础题：$f[u][0/1]$ 分别表示 $u$ 不参加/参加时子树最大快乐值。"}, {"oj": "AcWing", "pid": "291", "title": "蒙德里安的梦想", "diff": "提高", "hint": "棋盘状压 DP：先横放再竖放，预处理每列状态合法性（不含连续奇数个 $0$）。"}, {"oj": "AcWing", "pid": "300", "title": "任务安排1", "diff": "提高", "hint": "利用“费用提前计算”消除分批数维度，后续可用单调队列维护下凸壳做斜率优化。"}]}, {"cid": "0x60", "title": "图论基础与连通性（最短路、生成树与 Tarjan）", "summary": "本章系统梳理图论骨干算法：分层图最短路与差分约束系统（将不等式 $x_v - x_u \\le w$ 转化为最短路松弛）、Kruskal 重构树与次小生成树、树上倍增求最近公共祖先（LCA）与树上差分，以及 Tarjan 算法求有向图强连通分量（SCC，缩点为 DAG）和无向图割点、桥与双连通分量。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nconst int N = 100005;\nvector<int> g[N];\nint dfn[N], low[N], stk[N], scc[N], top, ts, scc_cnt;\nbool in_stk[N];\n\nvoid tarjan(int u) {\n    dfn[u] = low[u] = ++ts;\n    stk[++top] = u; in_stk[u] = true;\n    for (int v : g[u]) {\n        if (!dfn[v]) { tarjan(v); low[u] = min(low[u], low[v]); }\n        else if (in_stk[v]) low[u] = min(low[u], dfn[v]);\n    }\n    if (dfn[u] == low[u]) {\n        ++scc_cnt;\n        while (true) {\n            int x = stk[top--];\n            in_stk[x] = false;\n            scc[x] = scc_cnt;\n            if (x == u) break;\n        }\n    }\n}\n\nint main() { return 0; }", "pitfalls": "无向图求桥时忘记排除父边（尤其是有重边时需用边编号 `e ^ 1` 判重而非点编号 `v == fa`）；Tarjan 缩点后建新图未去重重边；差分约束未建立超级源点导致图不连通漏判负环。", "workbench_tags": ["图论", "树上问题"], "problems": [{"oj": "AcWing", "pid": "340", "title": "通信线路", "diff": "提高", "hint": "二分第 $K+1$ 大的边权 $mid$，将 $>mid$ 的边权置 $1$、$\\le mid$ 的置 $0$，跑 $0/1$ BFS 判断最短路是否 $\\le K$。"}, {"oj": "AcWing", "pid": "356", "title": "次小生成树", "diff": "省选", "hint": "先求 MST，再用树上倍增预处理任意两点路径上的最大边权与严格次大边权，枚举非树边替换。"}, {"oj": "AcWing", "pid": "362", "title": "区间", "diff": "提高", "hint": "设前缀和 $S[i]$，将区间至少选 $c_i$ 个数转化为差分约束 $S[b]-S[a-1]\\ge c$ 并跑最长路。"}, {"oj": "AcWing", "pid": "367", "title": "学校网络", "diff": "提高", "hint": "Tarjan 缩点为 DAG 后，第一问为入度为 $0$ 的点数，第二问为 $\\max(\\text{入度}0, \\text{出度}0)$（特判 $scc\\_cnt=1$）。"}]}, {"cid": "0x68", "title": "二分图与网络流（匹配、最大流与最小割）", "summary": "本章深入图论高级模型，围绕二分图判定（黑白染色）、匈牙利算法求最大匹配与最小点覆盖（König 定理）、2-SAT 布尔可满足性建模，以及 Dinic 算法（当前弧优化）求最大流、最大流最小割定理的经典建模（源汇割集划分互斥决策）与费用流。核心方法论在于识别模型中的对偶关系与流量守恒约束。", "template_cpp": "#include <vector>\n#include <queue>\nusing namespace std;\nstruct Dinic {\n    struct E { int v, rev; long long cap; };\n    vector<vector<E>> g; vector<int> lv, ptr;\n    Dinic(int n) : g(n), lv(n), ptr(n) {}\n    void add(int u, int v, long long c) {\n        g[u].push_back({v, (int)g[v].size(), c});\n        g[v].push_back({u, (int)g[u].size() - 1, 0});\n    }\n    bool bfs(int s, int t) {\n        fill(lv.begin(), lv.end(), -1);\n        queue<int> q; q.push(s); lv[s] = 0;\n        while (!q.empty()) {\n            int u = q.front(); q.pop();\n            for (auto &e : g[u]) if (e.cap > 0 && lv[e.v] == -1) { lv[e.v] = lv[u] + 1; q.push(e.v); }\n        }\n        return lv[t] != -1;\n    }\n    long long dfs(int u, int t, long long f) {\n        if (!f || u == t) return f;\n        for (int &i = ptr[u]; i < (int)g[u].size(); ++i) {\n            auto &e = g[u][i];\n            if (lv[e.v] == lv[u] + 1 && e.cap > 0)\n                if (long long tr = dfs(e.v, t, min(f, e.cap))) { e.cap -= tr; g[e.v][e.rev].cap += tr; return tr; }\n        }\n        return 0;\n    }\n};", "pitfalls": "Dinic 忘记加当前弧优化 `int &cid = ptr[u]` 导致分层图退化；匈牙利算法每轮未清空 `vis` 数组；最小割模型忘记将点容量拆点或反转边权符号。", "workbench_tags": ["图论"], "problems": [{"oj": "AcWing", "pid": "372", "title": "棋盘覆盖", "diff": "提高", "hint": "棋盘黑白染色建立二分图，禁用格子剔除后求最大匹配即可。"}, {"oj": "AcWing", "pid": "378", "title": "骑士放置", "diff": "提高", "hint": "日字形攻击关系只发生在异色格之间，转化为二分图最大独立集（总点数减最大匹配）。"}, {"oj": "AcWing", "pid": "380", "title": "舞动的夜晚", "diff": "省选", "hint": "先求完备匹配，再按匹配定向建图跑 Tarjan，同 SCC 内的非匹配边才是可行边。"}, {"oj": "AcWing", "pid": "382", "title": "K取方格数", "diff": "省选", "hint": "每个格子拆为入点出点，连一条容量 $1$ 费用为格子权值的边和一条容量 $\\infty$ 费用为 $0$ 的边，跑最大费用最大流。"}]}]}, {"id": "luo", "name": "罗勇军 · 算法竞赛（清华科技大讲堂）", "author": "罗勇军、郭卫斌", "level": "入门到提高", "repo_url": "https://github.com/luoyongjun999/code", "chapters": [{"cid": "Ch.01", "title": "基础数据结构（STL 与线性表）", "summary": "本章立足现代 C++ 竞赛工程实践，系统讲解线性表、链表、栈、队列、堆及 `vector`、`list`、`deque`、`priority_queue`、`set`、`map` 的底层原理与接口选型。核心思想是通过封装良好的 STL 容器替代手写繁琐指针，同时掌握双向链表静态模拟与双端队列单调性维护，兼顾编码速度与运行常数优化。", "template_cpp": "#include <iostream>\n#include <stack>\n#include <vector>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<int> h(n), ans(n, 0);\n    for (int &x : h) cin >> x;\n    stack<int> st;\n    for (int i = n - 1; i >= 0; --i) {\n        while (!st.empty() && h[st.top()] <= h[i]) st.pop();\n        ans[i] = st.empty() ? 0 : st.top() + 1;\n        st.push(i);\n    }\n    for (int x : ans) cout << x << ' ';\n    return 0;\n}", "pitfalls": "单调栈弹栈条件 `<` 与 `<=` 混淆；`priority_queue` 默认是大根堆，自定义结构体重载 `<` 时逻辑方向与 `sort` 相反；遍历容器时执行 `erase` 导致迭代器失效。", "workbench_tags": ["数据结构", "STL"], "problems": [{"oj": "Luogu", "pid": "P1996", "title": "约瑟夫问题", "diff": "入门", "hint": "使用循环队列或 `std::list` 模拟报数出队过程。"}, {"oj": "Luogu", "pid": "P1886", "title": "滑动窗口 /【模板】单调队列", "diff": "普及", "hint": "维护两个单调队列分别求窗口最小值和最大值，队内只存下标。"}, {"oj": "Luogu", "pid": "P5788", "title": "【模板】单调栈", "diff": "普及", "hint": "倒序扫描或正序压栈，维护严格单调递减栈求右侧首个更大元素下标。"}, {"oj": "Luogu", "pid": "P1090", "title": "合并果子", "diff": "普及", "hint": "哈夫曼树贪心思想，使用小根堆每次取出最小两堆合并后重新入堆。"}]}, {"cid": "Ch.02", "title": "基本算法（排序、二分、倍增与尺取）", "summary": "本章系统剖析竞赛基础核心思想：分治与归并排序求逆序对、整数与实数二分查找及二分答案、倍增思想（ST 表静态区间极值查询 $O(1)$）以及双指针尺取法（Two Pointers）。核心方法论在于发现序列的局部单调性或 $2^k$ 幂次可合并性，将嵌套循环优化至线性或对数级别。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <cmath>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n, m;\n    cin >> n >> m;\n    int lg = __lg(n);\n    vector<vector<int>> st(n + 1, vector<int>(lg + 1));\n    for (int i = 1; i <= n; ++i) cin >> st[i][0];\n    for (int j = 1; j <= lg; ++j)\n        for (int i = 1; i + (1 << j) - 1 <= n; ++i)\n            st[i][j] = max(st[i][j - 1], st[i + (1 << (j - 1))][j - 1]);\n    while (m--) {\n        int l, r; cin >> l >> r;\n        int k = __lg(r - l + 1);\n        cout << max(st[l][k], st[r - (1 << k) + 1][k]) << '\\n';\n    }\n    return 0;\n}", "pitfalls": "ST 表建表外层循环必须先枚举幂次 $j$ 再枚举起点 $i$；尺取法移动左指针时未同步撤销该元素对窗口状态的贡献；实数二分循环次数过少或过大导致超时/精度不足（固定迭代 $100$ 次最稳妥）。", "workbench_tags": ["排序与二分", "分治", "贪心"], "problems": [{"oj": "Luogu", "pid": "P3865", "title": "【模板】ST 表", "diff": "普及", "hint": "预处理倍增区间最大值数组，每次查询拆分为两个可重叠的 $2^k$ 区间取极值。"}, {"oj": "Luogu", "pid": "P2678", "title": "跳石头", "diff": "普及", "hint": "二分最小跳跃距离 $mid$，贪心检查间距小于 $mid$ 的石头移走数是否 $\\le M$。"}, {"oj": "Luogu", "pid": "P1908", "title": "逆序对", "diff": "普及", "hint": "归并排序合并左右有序段时累加跨段逆序对贡献，注意答案需用 `long long`。"}, {"oj": "Luogu", "pid": "P1638", "title": "逛画展", "diff": "普及", "hint": "双指针尺取法维护区间内不同画师种类数恰好为 $m$ 的最短子段。"}]}, {"cid": "Ch.03", "title": "搜索技术（BFS、DFS 与启发式搜索）", "summary": "本章完整构建状态空间搜索方法论，涵盖 DFS 递归回溯、BFS 无权图最短路、连通块与洪水填充、双向广搜（从起点和终点同时扩展以将状态数开方）、迭代加深搜索（IDDFS）以及 $A^*$ 与 $IDA^*$ 算法。核心在于合理设计状态编码方式（如二进制位压、哈希）与剪枝条件，避免无效扩展。", "template_cpp": "#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nconst int dx[] = {1, -1, 0, 0};\nconst int dy[] = {0, 0, 1, -1};\n\nint bfs(int n, int m, int sx, int sy, int tx, int ty, vector<string>& g) {\n    vector<vector<int>> d(n, vector<int>(m, -1));\n    queue<pair<int, int>> q;\n    d[sx][sy] = 0; q.push({sx, sy});\n    while (!q.empty()) {\n        auto [x, y] = q.front(); q.pop();\n        if (x == tx && y == ty) return d[x][y];\n        for (int i = 0; i < 4; ++i) {\n            int nx = x + dx[i], ny = y + dy[i];\n            if (nx >= 0 && nx < n && ny >= 0 && ny < m && g[nx][ny] != '#' && d[nx][ny] == -1) {\n                d[nx][ny] = d[x][y] + 1;\n                q.push({nx, ny});\n            }\n        }\n    }\n    return -1;\n}\nint main() { return 0; }", "pitfalls": "双向 BFS 时忘记在层数较小的一侧优先扩展导致两半失衡；DFS 记忆化搜索未区分当前路径“正在访问”与“已完成访问”；马走日等八方向数组坐标写错。", "workbench_tags": ["搜索", "图论"], "problems": [{"oj": "Luogu", "pid": "P1219", "title": "八皇后 Checker Challenge", "diff": "普及", "hint": "DFS 按行放置皇后，用列、主对角线、副对角线三个布尔数组 $O(1)$ 判冲突。"}, {"oj": "Luogu", "pid": "P1443", "title": "马的遍历", "diff": "普及", "hint": "标准八方向骑士步 BFS，从起点出发记录到达每个格子的最小步数。"}, {"oj": "Luogu", "pid": "P1379", "title": "八数码难题", "diff": "提高", "hint": "将 $3\\times 3$ 棋盘序列化为字符串或整数，用双向 BFS 或 $A^*$（曼哈顿距离估价）求解。"}, {"oj": "Luogu", "pid": "P1032", "title": "字串变换", "diff": "提高", "hint": "限制步数 $\\le 10$ 步的双向 BFS，用 `unordered_map` 记录两端最小步数。"}]}, {"cid": "Ch.04", "title": "高级数据结构（并查集、线段树与平衡树）", "summary": "本章系统剖析动态维护集合与区间的核心高级数据结构，包括路径压缩与按秩合并的并查集（含种类并查集与带权并查集）、树状数组、线段树（单点/区间修改、扫描线）、主席树（可持久化权值线段树求静态区间第 $k$ 小）以及 FHQ-Treap 无旋平衡树。核心思想是利用树高 $O(\\log n)$ 的平衡结构支持分裂、合并与历史版本共享。", "template_cpp": "#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct DSU {\n    vector<int> p, sz;\n    DSU(int n) : p(n + 1), sz(n + 1, 1) {\n        for (int i = 0; i <= n; ++i) p[i] = i;\n    }\n    int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }\n    bool unite(int a, int b) {\n        a = find(a); b = find(b);\n        if (a == b) return false;\n        if (sz[a] < sz[b]) swap(a, b);\n        p[b] = a; sz[a] += sz[b];\n        return true;\n    }\n};\n\nint main() {\n    DSU dsu(5);\n    dsu.unite(1, 2);\n    cout << (dsu.find(1) == dsu.find(2)) << '\\n';\n    return 0;\n}", "pitfalls": "主席树空间复杂度为 $O(n \\log n)$，常需开 `N * 25` 或 `N << 5` 的节点池；带权并查集在路径压缩时忘记先保存原父节点导致权值累加错乱；FHQ-Treap `split` 与 `merge` 时忘记 `pushdown`/`pushup`。", "workbench_tags": ["数据结构", "树形结构"], "problems": [{"oj": "Luogu", "pid": "P3367", "title": "【模板】并查集", "diff": "入门", "hint": "路径压缩配合按秩/按大小合并实现近似 $O(1)$ 集合合并与查询。"}, {"oj": "Luogu", "pid": "P3372", "title": "【模板】线段树 1", "diff": "普及", "hint": "经典区间加、区间求和线段树，维护 `sum` 与懒标记 `add`。"}, {"oj": "Luogu", "pid": "P3834", "title": "【模板】可持久化线段树 2", "diff": "省选", "hint": "离散化后逐个插入构建主席树，利用前缀和思想在两棵版本树上二分第 $k$ 小。"}, {"oj": "Luogu", "pid": "P3369", "title": "【模板】普通平衡树", "diff": "省选", "hint": "推荐使用 FHQ-Treap 按值分裂与合并，代码简洁且天然支持可持久化。"}]}, {"cid": "Ch.05", "title": "动态规划（背包、区间、树形、数位与状压）", "summary": "本章完整梳理动态规划六大经典模型：背包问题（0-1、完全、多重、分组、有依赖）、线性 DP（LCS/LIS）、区间 DP（石子合并）、树形 DP（树上背包与独立集）、数位 DP（记忆化搜索按位填数统计区间内满足性质的数个数）以及状态压缩 DP。核心方法论是清晰定义状态维度的无后效性边界与合法转移子集。", "template_cpp": "#include <iostream>\n#include <cstring>\nusing namespace std;\n\nint a[20];\nlong long dp[20][10];\n\nlong long dfs(int pos, int last, bool limit, bool lead) {\n    if (pos == 0) return 1;\n    if (!limit && !lead && dp[pos][last] != -1) return dp[pos][last];\n    int up = limit ? a[pos] : 9;\n    long long res = 0;\n    for (int d = 0; d <= up; ++d) {\n        if (!lead && abs(d - last) < 2) continue;\n        res += dfs(pos - 1, d, limit && (d == up), lead && (d == 0));\n    }\n    if (!limit && !lead) dp[pos][last] = res;\n    return res;\n}\nint main() { memset(dp, -1, sizeof(dp)); return 0; }", "pitfalls": "数位 DP 忘记传递 `lead`（前导零）标记导致 `0` 对相邻数字限制产生干扰，或把 `limit=true` 时的受限状态误存入全局 `dp` 记忆化表；环形区间 DP 破环成链后数组长度未翻倍为 $2n$。", "workbench_tags": ["DP", "树上问题"], "problems": [{"oj": "Luogu", "pid": "P1048", "title": "采药", "diff": "入门", "hint": "标准 0-1 背包问题，滚动一维数组倒序枚举容量。"}, {"oj": "Luogu", "pid": "P1880", "title": "石子合并", "diff": "普及", "hint": "破环成链复制为 $2n$ 长度，按区间长度 $len$ 从 $2$ 到 $n$ 枚举区间 DP。"}, {"oj": "Luogu", "pid": "P1352", "title": "没有上司的舞会", "diff": "普及", "hint": "树形 DP 基础模板，选或不选当前节点向子节点转移。"}, {"oj": "Luogu", "pid": "P2657", "title": "windy 数", "diff": "提高", "hint": "数位 DP 模板题，求解 $[1, R]$ 与 $[1, L-1]$ 答案作差，注意处理前导零。"}]}, {"cid": "Ch.06", "title": "数论与组合数学（素数、同余、CRT 与博弈）", "summary": "本章涵盖竞赛核心数论与组合工具：整除与素数（埃氏筛与欧拉线性筛）、最大公约数与扩展欧几里得、乘法逆元（费马小定理与线性递推求 $1\\sim n$ 逆元）、中国剩余定理、Lucas 定理求解大组合数取模、容斥原理以及威佐夫博弈与 Nim 游戏。核心在于借助同余代数性质把指数与组合爆炸化简到多项式复杂度。", "template_cpp": "#include <iostream>\n#include <vector>\nusing namespace std;\nusing ll = long long;\nconst ll MOD = 1e9 + 7;\n\nll qpow(ll a, ll b) {\n    ll res = 1;\n    for (a %= MOD; b; b >>= 1, a = a * a % MOD)\n        if (b & 1) res = res * a % MOD;\n    return res;\n}\n\nint main() {\n    int n = 100000;\n    vector<ll> fac(n + 1, 1), inv(n + 1, 1);\n    for (int i = 1; i <= n; ++i) fac[i] = fac[i - 1] * i % MOD;\n    inv[n] = qpow(fac[n], MOD - 2);\n    for (int i = n - 1; i >= 1; --i) inv[i] = inv[i + 1] * (i + 1) % MOD;\n    cout << fac[5] * inv[2] % MOD * inv[3] % MOD << '\\n';\n    return 0;\n}", "pitfalls": "Lucas 定理 $C(n, m) \\bmod p$ 仅适用于模数 $p$ 为较小素数；预处理阶乘逆元时递推方向写反或忘记给 `inv[0] = 1`；Nim 博弈误将石子数直接相加而非异或。", "workbench_tags": ["数学", "博弈论"], "problems": [{"oj": "Luogu", "pid": "P3383", "title": "【模板】线性筛素数", "diff": "普及", "hint": "欧拉筛保证每个合数只被其最小质因子筛去一次，实现严格 $O(n)$ 复杂度。"}, {"oj": "Luogu", "pid": "P3811", "title": "【模板】模意义下的乘法逆元", "diff": "普及", "hint": "使用线性递推公式 `inv[i] = (p - p/i) * inv[p%i] % p` 在 $O(n)$ 内求全部逆元。"}, {"oj": "Luogu", "pid": "P3807", "title": "【模板】卢卡斯定理/Lucas 定理", "diff": "提高", "hint": "将 $n, m$ 转为 $p$ 进制按位递归计算小组合数乘积。"}, {"oj": "Luogu", "pid": "P2197", "title": "【模板】Nim 游戏", "diff": "普及", "hint": "计算所有石子堆数量的异或和，非 $0$ 则先手必胜，否则先手必败。"}]}, {"cid": "Ch.07", "title": "字符串算法（Hash、KMP、Trie 与 AC 自动机）", "summary": "本章深入现代字符串匹配与自动机理论，覆盖滚动哈希与双哈希、KMP 算法的前缀函数（`next` 数组）及其在最小循环节中的应用、Manacher 算法 $O(n)$ 求解最长回文子串、字典树 Trie 以及融合 KMP 失配指针的多模式串匹配利器 AC 自动机。核心思想是利用已匹配前缀的对称性或自动机状态转移避免指针回溯。", "template_cpp": "#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvector<int> build_pi(const string& p) {\n    int m = p.size();\n    vector<int> pi(m, 0);\n    for (int i = 1, j = 0; i < m; ++i) {\n        while (j > 0 && p[i] != p[j]) j = pi[j - 1];\n        if (p[i] == p[j]) j++;\n        pi[i] = j;\n    }\n    return pi;\n}\n\nint main() {\n    string s = \"ababcabc\", p = \"abc\";\n    auto pi = build_pi(p);\n    for (int i = 0, j = 0; i < (int)s.size(); ++i) {\n        while (j > 0 && s[i] != p[j]) j = pi[j - 1];\n        if (s[i] == p[j]) j++;\n        if (j == (int)p.size()) { cout << i - j + 1 << '\\n'; j = pi[j - 1]; }\n    }\n    return 0;\n}", "pitfalls": "AC 自动机构建 `fail` 指针未用 BFS 按深度层序构建，或忘记把根节点的直连空边加入队列；KMP 匹配成功后未将 `j` 回退至 `pi[j-1]` 导致漏掉重叠匹配；Manacher 插入分隔符后下标未除以 $2$。", "workbench_tags": ["字符串", "数据结构"], "problems": [{"oj": "Luogu", "pid": "P3375", "title": "【模板】KMP", "diff": "普及", "hint": "线性计算模式串前缀函数 `pi[]`，匹配文本串并输出所有出现位置及 `border` 长度。"}, {"oj": "Luogu", "pid": "P3805", "title": "【模板】manacher", "diff": "提高", "hint": "在字符间插入 `#` 统一奇偶回文，维护最右回文边界 $r$ 与对称中心 $mid$。"}, {"oj": "Luogu", "pid": "P3808", "title": "AC 自动机（简单版）", "diff": "提高", "hint": "将所有模式串插入 Trie 后 BFS 建 `fail` 树，文本串跑匹配并标记已统计节点避免重复。"}, {"oj": "Luogu", "pid": "P3370", "title": "【模板】字符串哈希", "diff": "入门", "hint": "采用双哈希或 `unsigned long long` 自然溢出哈希后排序去重计数。"}]}, {"cid": "Ch.08", "title": "图论算法（最短路、生成树、LCA 与网络流）", "summary": "本章完整覆盖图论核心模块：链式前向星与邻接表存图、拓扑排序、Dijkstra 与 Floyd 算法、Kruskal 最小生成树、倍增与树链剖分求 LCA、Tarjan 求强连通分量与割点/桥、二分图匹配以及 Dinic 最大流。核心方法论在于区分有向图与无向图拓扑结构差异，并将树上路径查询转化为 LCA 拆解。", "template_cpp": "#include <iostream>\n#include <vector>\nusing namespace std;\n\nconst int N = 100005, LOG = 18;\nvector<int> g[N];\nint up[N][LOG], dep[N];\n\nvoid dfs(int u, int fa) {\n    up[u][0] = fa;\n    for (int j = 1; j < LOG; ++j) up[u][j] = up[up[u][j - 1]][j - 1];\n    for (int v : g[u]) if (v != fa) {\n        dep[v] = dep[u] + 1;\n        dfs(v, u);\n    }\n}\n\nint lca(int u, int v) {\n    if (dep[u] < dep[v]) swap(u, v);\n    for (int j = LOG - 1; j >= 0; --j)\n        if (dep[up[u][j]] >= dep[v]) u = up[u][j];\n    if (u == v) return u;\n    for (int j = LOG - 1; j >= 0; --j)\n        if (up[u][j] != up[v][j]) { u = up[u][j]; v = up[v][j]; }\n    return up[u][0];\n}\nint main() { return 0; }", "pitfalls": "倍增 LCA 未先将 $dep[0]$ 置 $0$（根深度需为 $1$），导致跳出根节点后深度误判；Floyd 三重循环最外层未放中转点 $k$；SPFA 判负环在非连通图上未将所有点入队。", "workbench_tags": ["图论", "树上问题"], "problems": [{"oj": "Luogu", "pid": "P4779", "title": "【模板】单源最短路径（标准版）", "diff": "普及", "hint": "使用小根堆优化的 Dijkstra 算法在 $O(m \\log n)$ 内求解非负权图最短路。"}, {"oj": "Luogu", "pid": "P3379", "title": "【模板】最近公共祖先（LCA）", "diff": "普及", "hint": "预处理倍增表 `up[u][j]`，查询时先跳齐深度再同步上跳。"}, {"oj": "Luogu", "pid": "P3387", "title": "【模板】缩点", "diff": "提高", "hint": "Tarjan 求 SCC 缩点后构造 DAG，在拓扑序上做 DP 求最长点权路径。"}, {"oj": "Luogu", "pid": "P3376", "title": "【模板】网络最大流", "diff": "提高", "hint": "Dinic 算法结合分层图 BFS 与当前弧优化 DFS 求最大流。"}]}, {"cid": "Ch.09", "title": "计算几何（向量、凸包与旋转卡壳）", "summary": "本章构建平面计算几何的代数基础，核心方法论是用向量点积与叉积替代繁琐三角函数与斜率分类讨论（规避垂直直线斜率无穷大问题）。重点涵盖点线位置关系、线段相交判定、极角排序、Andrew 算法 $O(n \\log n)$ 求二维凸包、旋转卡壳求凸包直径以及半平面交。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nstruct Pt {\n    double x, y;\n    bool operator<(const Pt& o) const { return x != o.x ? x < o.x : y < o.y; }\n    Pt operator-(const Pt& o) const { return {x - o.x, y - o.y}; }\n};\ndouble cross(Pt a, Pt b) { return a.x * b.y - a.y * b.x; }\n\nvector<Pt> convex_hull(vector<Pt>& p) {\n    sort(p.begin(), p.end());\n    vector<Pt> h;\n    for (int i = 0; i < (int)p.size(); ++i) {\n        while (h.size() >= 2 && cross(h.back() - h[h.size()-2], p[i] - h.back()) <= 0) h.pop_back();\n        h.push_back(p[i]);\n    }\n    for (int i = (int)p.size() - 2, t = h.size() + 1; i >= 0; --i) {\n        while ((int)h.size() >= t && cross(h.back() - h[h.size()-2], p[i] - h.back()) <= 0) h.pop_back();\n        h.push_back(p[i]);\n    }\n    if (h.size() > 1) h.pop_back();\n    return h;\n}\nint main() { return 0; }", "pitfalls": "浮点叉积判断共线未引入 `eps`（$10^{-9}$）导致退化三点共线死循环；旋转卡壳未特判凸包仅剩 $2$ 个点的退化情况；线段相交仅做跨立实验而忽略共线重叠时的快速排斥实验。", "workbench_tags": ["计算几何", "数学"], "problems": [{"oj": "Luogu", "pid": "P2742", "title": "【模板】二维凸包", "diff": "提高", "hint": "Andrew 算法先排序再分别构建下凸壳与上凸壳，最后累加相邻点欧氏距离。"}, {"oj": "Luogu", "pid": "P1452", "title": "【模板】旋转卡壳 | [USACO03FALL] Beauty Contest G", "diff": "提高", "hint": "先求二维凸包，再逆时针双指针枚举每条边及其最远对踵点更新最大距离平方。"}, {"oj": "Luogu", "pid": "P4196", "title": "【模板】半平面交", "diff": "省选", "hint": "按有向直线极角排序后用双端队列维护凸多边形交集，注意先弹队尾再弹队头。"}]}, {"cid": "Ch.10", "title": "综合专题与现代 C++ 工程技巧", "summary": "本章聚焦提高到省选阶段的离线分治技巧与工程鲁棒性，涵盖坐标离散化、CDQ 分治解决三维偏序问题（排序消第一维、分治消第二维、树状数组维第三维）、整体二分处理多组静态第 $k$ 小询问，以及快读模板、随机化（`mt19937`）与对拍脚本规范。核心思想是将动态在线查询转化为离线批处理分治。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <random>\n#include <chrono>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());\n    vector<int> a = {100, 20, 100, 5, 20};\n    vector<int> vals = a;\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    for (int &x : a) {\n        x = lower_bound(vals.begin(), vals.end(), x) - vals.begin() + 1;\n        cout << x << ' ';\n    }\n    cout << '\\n' << (rng() % 100) << '\\n';\n    return 0;\n}", "pitfalls": "CDQ 分治排序未把完全相同的三元组先合并去重导致相互偏序贡献漏算；离散化后数组大小未按去重后的元素总数（特别是包含查询值时为 $2n$）开辟；使用 `rand()` 在 Windows 下最大值仅 $32767$ 应改用 `mt19937`。", "workbench_tags": ["分治", "数据结构", "竞赛术语与代码工程"], "problems": [{"oj": "Luogu", "pid": "P3810", "title": "【模板】三维偏序（陌上花开）", "diff": "省选", "hint": "先去重统计相同元素个数，再按 $a$ 排序后 CDQ 分治内按 $b$ 归并并用树状数组统计 $c$。"}, {"oj": "Luogu", "pid": "P3527", "title": "【POI2011】MET-Meteors", "diff": "省选", "hint": "整体二分所有国家的达标时刻，每次将陨石雨批量修改树状数组并划分子集递归。"}, {"oj": "Luogu", "pid": "P1496", "title": "火烧赤壁", "diff": "普及", "hint": "将所有区间端点离散化后在差分数组上区间加 $1$，统计非零覆盖总长度。"}]}]}, {"id": "cph", "name": "CPH · Competitive Programmer's Handbook", "author": "Antti Laaksonen", "level": "英文精炼", "repo_url": "https://cses.fi/book/", "chapters": [{"cid": "M01", "title": "Introduction, Complexity & Sorting", "summary": "本模块对应 CPH 第 1–3 章，以极简现代 C++ 风格切入时间复杂度分析（含均摊复杂度与 $O(n^2)$ 到 $O(n \\log n)$ 的规模界限）及最大子段和的 Kadane 算法。核心方法论在于通过 `std::sort` 与自定义比较器将无序输入转化为有序结构，从而开启二分查找与扫描线等高效后续操作。", "template_cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    long long best = -1e18, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        long long x;\n        cin >> x;\n        cur = max(x, cur + x);\n        best = max(best, cur);\n    }\n    cout << best << '\\n';\n    return 0;\n}", "pitfalls": "最大子段和全部元素为负数时，初值误设为 $0$ 导致错误返回空子段（若题目要求非空）；忽略 `sort` 最坏情况与稳定排序需求。", "workbench_tags": ["复杂度", "排序与二分"], "problems": [{"oj": "CSES", "pid": "1068", "title": "Weird Algorithm", "diff": "入门", "hint": "模拟 Collatz 猜想迭代，注意中间值会超过 $32$ 位整数上限，需用 `long long`。"}, {"oj": "CSES", "pid": "1083", "title": "Missing Number", "diff": "入门", "hint": "用等差数列和 $n(n+1)/2$ 减去输入之和（或异或性质）求缺失值。"}, {"oj": "CSES", "pid": "1621", "title": "Distinct Numbers", "diff": "入门", "hint": "排序后统计相邻不等元素个数，或直接插入 `set`（注意常量开销）。"}, {"oj": "CSES", "pid": "1084", "title": "Apartments", "diff": "普及", "hint": "将申请者期望与公寓面积同时排序，使用双指针贪心匹配。"}]}, {"cid": "M02", "title": "Data Structures & Bit Manipulation", "summary": "本模块涵盖 CPH 第 4、10 章，精炼对比动态数组、集合、映射、优先队列以及位运算集合表示法（Bitmask）。核心方法论是利用整数二进制位表达 $n \\le 20$ 的子集并实现 $O(1)$ 交并补运算，同时借助 `std::set` 的二分迭代器 `lower_bound` 维护动态插入与删除的区间切割状态。", "template_cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n = 4;\n    for (int mask = 0; mask < (1 << n); ++mask) {\n        cout << \"popcount=\" << __builtin_popcount(mask) << \": \";\n        for (int i = 0; i < n; ++i)\n            if (mask & (1 << i)) cout << i << ' ';\n        cout << '\\n';\n    }\n    return 0;\n}", "pitfalls": "使用 `std::lower_bound(s.begin(), s.end(), x)` 替代 `s.lower_bound(x)` 导致在 `set` 上退化为 $O(n)$ 线性遍历；`1 << i` 在 $i \\ge 31$ 时未写 `1LL << i` 发生未定义行为。", "workbench_tags": ["数据结构", "STL", "位运算"], "problems": [{"oj": "CSES", "pid": "1619", "title": "Restaurant Customers", "diff": "普及", "hint": "将到达记为 $+1$、离开记为 $-1$ 事件，排序后扫描线求最大并发前缀和。"}, {"oj": "CSES", "pid": "1640", "title": "Sum of Two Values", "diff": "入门", "hint": "排序后双指针夹逼，或用 `map` 存储已遍历元素下标。"}, {"oj": "CSES", "pid": "1163", "title": "Traffic Lights", "diff": "普及", "hint": "用 `set` 维护红绿灯位置，同时用 `multiset` 维护所有相邻区段长度动态极值。"}, {"oj": "CSES", "pid": "1091", "title": "Concert Tickets", "diff": "普及", "hint": "将票价存入 `multiset`，对每位顾客调用 `upper_bound(t)` 并前移一位匹配。"}]}, {"cid": "M03", "title": "Complete Search & Greedy Algorithms", "summary": "本模块整合 CPH 第 5–6 章，聚焦递归回溯、折半搜索（Meet-in-the-middle）与经典贪心模型（区间调度、任务截止时间优化、数据压缩）。核心方法论在于结合局部最优选择证明全局最优性，并在指数级搜索中通过对称性剪枝与可行性预判压缩递归树规模。", "template_cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<pair<int, int>> ev(n);\n    for (auto &[a, b] : ev) cin >> a >> b;\n    sort(ev.begin(), ev.end(), [](auto &x, auto &y) {\n        return x.second < y.second;\n    });\n    int cnt = 0, last_end = -1;\n    for (auto [a, b] : ev) {\n        if (a >= last_end) { cnt++; last_end = b; }\n    }\n    cout << cnt << '\\n';\n    return 0;\n}", "pitfalls": "区间调度误按左端点或区间长度排序而非右端点升序；任务调度问题未按耗时升序排列导致总惩罚增大。", "workbench_tags": ["搜索", "贪心", "枚举"], "problems": [{"oj": "CSES", "pid": "1622", "title": "Creating Strings", "diff": "入门", "hint": "排序后循环调用 `std::next_permutation` 生成所有不重复排列。"}, {"oj": "CSES", "pid": "1624", "title": "Chessboard and Queens", "diff": "普及", "hint": "带障碍格的 $8$ 皇后回溯搜索，利用三个布尔数组判重。"}, {"oj": "CSES", "pid": "1629", "title": "Movie Festival", "diff": "普及", "hint": "经典区间调度贪心：按结束时间升序排序并贪心选择互不重叠电影。"}, {"oj": "CSES", "pid": "1074", "title": "Stick Lengths", "diff": "普及", "hint": "使 $\\sum |x_i - c|$ 最小的最优目标值 $c$ 为序列中位数。"}]}, {"cid": "M04", "title": "Dynamic Programming", "summary": "本模块对应 CPH 第 7 章，以极其精炼的视角阐述动态规划的两种等价实现（记忆化递归与迭代递推）。涵盖硬币找零（组合数 vs 排列数循环顺序差异）、最长递增子序列（$O(n \\log n)$ 贪心二分维护尾部最小值）、网格路径、编辑距离及背包与子集状压 DP（电梯乘梯最小次数）。", "template_cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<int> tails;\n    for (int i = 0, x; i < n; ++i) {\n        cin >> x;\n        auto it = lower_bound(tails.begin(), tails.end(), x);\n        if (it == tails.end()) tails.push_back(x);\n        else *it = x;\n    }\n    cout << tails.size() << '\\n';\n    return 0;\n}", "pitfalls": "求硬币组合数（无序）与排列数（有序）时，外层遍历金额与外层遍历硬币种类的循环嵌套顺序颠倒；严格递增（`lower_bound`）与非递减（`upper_bound`）混淆。", "workbench_tags": ["DP"], "problems": [{"oj": "CSES", "pid": "1633", "title": "Dice Combinations", "diff": "入门", "hint": "线性 DP：$dp[x] = \\sum_{d=1}^6 dp[x-d] \\pmod{10^9+7}$。"}, {"oj": "CSES", "pid": "1634", "title": "Minimizing Coins", "diff": "普及", "hint": "完全背包求最小物品数，初值设为 `INF`，`dp[0] = 0`。"}, {"oj": "CSES", "pid": "1635", "title": "Coin Combinations I", "diff": "普及", "hint": "有序硬币凑数：外层枚举金额 $1\\sim x$，内层枚举所有硬币面值。"}, {"oj": "CSES", "pid": "1158", "title": "Book Shop", "diff": "普及", "hint": "标准 0-1 背包求最大页数，使用一维滚动数组倒序更新。"}]}, {"cid": "M05", "title": "Amortized Analysis & Range Queries", "summary": "本模块整合 CPH 第 8–9 章，剖析双指针均摊分析、最近更小元素单调栈、静态区间查询（前缀和与稀疏表 ST）以及动态区间查询（树状数组与自底向上非递归线段树）。核心方法论在于以均摊 $O(1)$ 消除重复扫描，并通过非递归线段树极简代码在 $O(\\log n)$ 内完成区间合并。", "template_cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nstruct SegTree {\n    int n;\n    vector<long long> tr;\n    SegTree(int n) : n(n), tr(2 * n, 0) {}\n    void update(int p, long long v) {\n        for (tr[p += n] = v; p > 1; p >>= 1)\n            tr[p >> 1] = tr[p] + tr[p ^ 1];\n    }\n    long long query(int l, int r) { // [l, r)\n        long long res = 0;\n        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {\n            if (l & 1) res += tr[l++];\n            if (r & 1) res += tr[--r];\n        }\n        return res;\n    }\n};\nint main() { return 0; }", "pitfalls": "非递归线段树查询区间为左闭右开 `[l, r)`，传参时未将右端点加 $1$；动态区间和未开 `long long` 导致超过 $2^{31}-1$ 溢出。", "workbench_tags": ["数据结构", "树形结构"], "problems": [{"oj": "CSES", "pid": "1643", "title": "Maximum Subarray Sum", "diff": "入门", "hint": "Kadane 算法或前缀和减去历史最小前缀和。"}, {"oj": "CSES", "pid": "1646", "title": "Static Range Sum Queries", "diff": "入门", "hint": "构建一维前缀和数组 $P[i]$，$O(1)$ 回答 $P[r]-P[l-1]$。"}, {"oj": "CSES", "pid": "1648", "title": "Dynamic Range Sum Queries", "diff": "普及", "hint": "树状数组或线段树支持单点修改与区间求和。"}, {"oj": "CSES", "pid": "1649", "title": "Dynamic Range Minimum Queries", "diff": "普及", "hint": "由于最小值无逆元不可减，必须使用线段树维护区间极值。"}]}, {"cid": "M06", "title": "Graph Algorithms", "summary": "本模块涵盖 CPH 第 11–13、15–16 章，系统串讲图论核心算法链：DFS/BFS 连通性与二分图染色、Dijkstra/Bellman-Ford/Floyd 最短路、DAG 拓扑排序与关键路径 DP、后继图（Functional Graph）倍增与 Floyd 判圈法，以及 Kruskal 最小生成树与并查集。", "template_cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n, m;\n    cin >> n >> m;\n    vector<tuple<int, int, int>> edges(m);\n    for (auto &[w, u, v] : edges) cin >> u >> v >> w;\n    sort(edges.begin(), edges.end());\n    vector<int> p(n + 1);\n    iota(p.begin(), p.end(), 0);\n    auto find = [&](auto &self, int x) -> int { return p[x] == x ? x : p[x] = self(self, p[x]); };\n    long long mst = 0; int cnt = 0;\n    for (auto [w, u, v] : edges) {\n        int a = find(find, u), b = find(find, v);\n        if (a != b) { p[a] = b; mst += w; cnt++; }\n    }\n    cout << (cnt == n - 1 ? to_string(mst) : \"IMPOSSIBLE\") << '\\n';\n    return 0;\n}", "pitfalls": "Kruskal 未检查最终合并边数是否等于 $n-1$ 而漏判图不连通；Floyd 存在负环或重边时未保留最小边权初始化矩阵。", "workbench_tags": ["图论"], "problems": [{"oj": "CSES", "pid": "1192", "title": "Counting Rooms", "diff": "入门", "hint": "二维网格四连通 DFS/BFS 统计 `.` 构成的连通块数量。"}, {"oj": "CSES", "pid": "1193", "title": "Labyrinth", "diff": "普及", "hint": "BFS 寻找起点到终点最短路径，同时记录每个格子的前驱方向字符用于回溯还原路径。"}, {"oj": "CSES", "pid": "1671", "title": "Shortest Routes I", "diff": "普及", "hint": "标准有向正权图单源最短路，使用堆优化 Dijkstra。"}, {"oj": "CSES", "pid": "1675", "title": "Road Reparation", "diff": "普及", "hint": "Kruskal 求无向图最小生成树，若边数不足 $n-1$ 输出 `IMPOSSIBLE`。"}]}, {"cid": "M07", "title": "Tree Algorithms", "summary": "本模块对应 CPH 第 14、18 章，聚焦树上经典算法体系：树直径的两次 BFS/DFS 与 DP 做法、每个节点的最远距离（换根 DP）、Euler Tour 欧拉序将子树与路径拍平为线性区间配合树状数组维护、倍增求 $k$-th 祖先与 LCA，以及启发式合并（Small-to-Large Merging）优化子树颜色统计。", "template_cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nconst int N = 200005;\nvector<int> g[N];\nint tin[N], tout[N], timer = 0;\n\nvoid dfs_euler(int u, int fa) {\n    tin[u] = ++timer;\n    for (int v : g[u]) {\n        if (v != fa) dfs_euler(v, u);\n    }\n    tout[u] = timer;\n}\n\nint main() {\n    g[1].push_back(2); g[2].push_back(1);\n    dfs_euler(1, 0);\n    cout << tin[1] << ' ' << tout[1] << '\\n';\n    return 0;\n}", "pitfalls": "欧拉序 `tout[u]` 记录时机混淆（子树区间为 `[tin[u], tout[u]]` 时仅入栈递增时间戳即可，若做路径差分则需入栈出栈均加时间戳）；启发式合并忘记使用 `swap` 导致 $O(n^2)$ 拷贝。", "workbench_tags": ["树上问题", "图论", "数据结构"], "problems": [{"oj": "CSES", "pid": "1674", "title": "Subordinates", "diff": "入门", "hint": "一次 DFS 统计每棵子树的节点总数减 $1$ 即为下属人数。"}, {"oj": "CSES", "pid": "1131", "title": "Tree Diameter", "diff": "普及", "hint": "任选一点 DFS 找到最远点 $u$，再从 $u$ 出发找到最远点 $v$，距离即树直径。"}, {"oj": "CSES", "pid": "1132", "title": "Tree Distances I", "diff": "提高", "hint": "先求直径两端点 $a, b$，树上任意点最远距离必为 $\\max(dist(x,a), dist(x,b))$。"}, {"oj": "CSES", "pid": "1688", "title": "Company Queries II", "diff": "普及", "hint": "标准最近公共祖先（LCA）查询，倍增或欧拉序 RMQ 均可求解。"}]}, {"cid": "M08", "title": "Mathematics & Number Theory", "summary": "本模块整合 CPH 第 21–25 章，精炼竞赛数学核心：素数筛选与质因数分解、欧拉函数与模逆元、阶乘预处理二项式系数、Catalan 数、矩阵快速幂解线性递推、容斥原理以及公平组合博弈（Nim 与 Grundy 数）。核心方法论是通过同余代数与矩阵幂将指数规模计算压缩至对数时间。", "template_cpp": "#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\nconst ll MOD = 1e9 + 7;\n\nll modpow(ll a, ll b, ll m = MOD) {\n    ll res = 1;\n    a %= m;\n    while (b > 0) {\n        if (b & 1) res = res * a % m;\n        a = a * a % m;\n        b >>= 1;\n    }\n    return res;\n}\n\nint main() {\n    int t; cin >> t;\n    while (t--) {\n        ll a, b; cin >> a >> b;\n        cout << modpow(a, b) << '\\n';\n    }\n    return 0;\n}", "pitfalls": "计算 $a^{b^c} \\bmod p$ 时误将指数直接对 $p$ 取模而非由费马小定理对 $p-1$ 取模；组合数未特判 $n < m$ 返回 $0$。", "workbench_tags": ["数学", "博弈论"], "problems": [{"oj": "CSES", "pid": "1095", "title": "Exponentiation", "diff": "入门", "hint": "快速幂求 $a^b \\bmod (10^9+7)$，注意 $0^0$ 按题面约定输出 $1$。"}, {"oj": "CSES", "pid": "1713", "title": "Counting Divisors", "diff": "入门", "hint": "$O(\\sqrt{x})$ 试除法或预处理最小质因子在 $O(\\log x)$ 内统计约数个数。"}, {"oj": "CSES", "pid": "1081", "title": "Common Divisors", "diff": "普及", "hint": "开桶记录值域 $1\\sim 10^6$ 内每个数出现次数，从大到小枚举公约数 $g$ 统计其倍数总出现次数是否 $\\ge 2$。"}, {"oj": "CSES", "pid": "1715", "title": "Creating Strings II", "diff": "普及", "hint": "多重集全排列公式 $\\frac{n!}{\\prod c_i!}$，预处理阶乘与阶乘逆元求解。"}]}, {"cid": "M09", "title": "String Algorithms", "summary": "本模块对应 CPH 第 26 章，系统介绍字符串核心算法：Trie 字典树、多项式滚动哈希（Polynomial Hashing）、Z 算法（Z-array 维护每个位置与原串的最长公共前缀长度）以及后缀数组在子串计数与字典序最小旋转串中的应用。核心思想是通过 Z 数组或哈希实现线性时间模式匹配与回文/周期检测。", "template_cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nvector<int> z_function(const string& s) {\n    int n = s.size();\n    vector<int> z(n, 0);\n    for (int i = 1, l = 0, r = 0; i < n; ++i) {\n        if (i <= r) z[i] = min(r - i + 1, z[i - l]);\n        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;\n        if (i + z[i] - 1 > r) { l = i; r = i + z[i] - 1; }\n    }\n    return z;\n}\n\nint main() {\n    auto z = z_function(\"abacaba\");\n    for (int x : z) cout << x << ' ';\n    return 0;\n}", "pitfalls": "滚动哈希单模数 $10^9+7$ 在构造数据下易碰撞，建议双模数或随机基数；Z 算法拼接 `pattern + '#' + text` 时忘记分隔符不能在原串中出现。", "workbench_tags": ["字符串"], "problems": [{"oj": "CSES", "pid": "1753", "title": "String Matching", "diff": "普及", "hint": "使用 KMP 或 Z 算法在线性时间内统计模式串出现次数。"}, {"oj": "CSES", "pid": "1731", "title": "Word Combinations", "diff": "提高", "hint": "将词典建为 Trie 树，从后往前线性 DP 枚举以当前位置为起点的所有词典匹配。"}, {"oj": "CSES", "pid": "1732", "title": "Finding Borders", "diff": "普及", "hint": "计算 Z 数组或 KMP 的 `pi` 数组，所有满足 `i + z[i] == n` 的后缀长度均为 Border。"}, {"oj": "CSES", "pid": "1110", "title": "Minimal Rotation", "diff": "提高", "hint": "Duval 算法或最小表示法双指针在 $O(n)$ 时间内求出字典序最小的循环移位。"}]}, {"cid": "M10", "title": "Advanced Graph & Geometry", "summary": "本模块整合 CPH 第 17、19–20、29 章，涵盖强连通分量与 2-SAT 问题、欧拉路径与哈密顿路径（状压 DP）、Ford-Fulkerson/Edmonds-Karp/Dinic 最大流与最小割及二分图匹配，以及复数（`std::complex`）简化二维计算几何、多边形面积（鞋带公式）与 Andrew 凸包。核心思想是借助高阶图论与复数代数工具直击难题本质。", "template_cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nstruct P { long long x, y; };\nlong long cross(P a, P b, P c) {\n    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<P> p(n);\n    for (auto &[x, y] : p) cin >> x >> y;\n    long long area2 = 0;\n    for (int i = 0; i < n; ++i) {\n        int j = (i + 1) % n;\n        area2 += p[i].x * p[j].y - p[j].x * p[i].y;\n    }\n    cout << llabs(area2) << '\\n';\n    return 0;\n}", "pitfalls": "多边形鞋带公式计算两倍有向面积时中间项可能超出 `int` 需用 `long long`；欧拉路径未验证图连通性及起点出度入度差；最小割输出割边集合时忘记在残量网络从源点 BFS 寻找可达集。", "workbench_tags": ["图论", "计算几何"], "problems": [{"oj": "CSES", "pid": "1694", "title": "Download Speed", "diff": "提高", "hint": "标准有向图最大流问题，注意重边流量叠加与总流需开 `long long`。"}, {"oj": "CSES", "pid": "1695", "title": "Police Chase", "diff": "提高", "hint": "跑完最大流后在残量网络从 $1$ 号点 DFS/BFS 标记可达点集 $S$，连接 $S$ 与非 $S$ 的原图边即最小割。"}, {"oj": "CSES", "pid": "2189", "title": "Point Location Test", "diff": "入门", "hint": "利用向量叉积 $(p_2-p_1)\\times(p_3-p_1)$ 的正负性直接判定点在有向直线左侧、右侧或共线。"}, {"oj": "CSES", "pid": "2195", "title": "Convex Hull", "diff": "提高", "hint": "Andrew 凸包算法，注意本题要求保留凸包边上的共线点，退栈条件用严格 `< 0`。"}]}]}, {"id": "gh_bupt_icpc", "name": "🎓 GitHub 伴读资源 & 北邮计导/算法课攻略", "author": "aoapc-bac2nd · tedukuri · luoyongjun999 · faranten", "level": "官方源码库 + 校内攻略", "repo_url": "https://github.com/lydrainbowcat/tedukuri", "chapters": [{"cid": "GH-ICPC-01", "title": "紫书/蓝书/罗勇军 GitHub 官方源码库与北邮计导/算法课攻略", "summary": "1) 紫书官方源码库 aoapc-book/aoapc-bac2nd（2.8k stars）按 ch3–ch12 收录全部例题标准 C++ 程序；2) 蓝书资源社区 lydrainbowcat/tedukuri（2.6k stars）提供全书 99% 题目的测试数据、勘误 PDF 与 AcWing/Contest Hunter 题单映射；3) 罗勇军《算法竞赛》源码库 luoyongjun999/code 按章节收录现代 C++ 实现。4) 北邮校内注意：《计算导论与程序设计》为 4 学分重课，平时多练编程但期末务必背熟基础概念；《算法设计与分析》期末基本只考课上 PPT 讲过的算法，吃透每页 PPT 即可稳拿高分。", "template_cpp": "三大 GitHub 伴读仓库：\n• 紫书源码: https://github.com/aoapc-book/aoapc-bac2nd\n• 蓝书数据与勘误: https://github.com/lydrainbowcat/tedukuri\n• 罗勇军源码: https://github.com/luoyongjun999/code", "pitfalls": "只刷 OJ 忽略校内《计算导论》期末概念背诵，或刷蓝书老题找不到 BZOJ 题面时没去 AcWing/OpenJudge 查重名题。", "workbench_tags": ["GitHub资源", "北邮考情"], "problems": []}]}];
window.__WB_CHEATSHEET__ = {"title": "ICPC 算法竞赛考前1页纸速查卡", "sections": [{"heading": "一、时间复杂度与数据范围反推表", "items": [{"name": "$n \\le 20$（指数/状压级）", "formula": "$O(2^n)$ 或 $O(n \\cdot 2^n)$ 或 $O(n!)$", "note": "状压 DP、折半搜索 Meet-in-the-Middle（$n \\le 40$ 拆成 $2^{20}$）、DFS 剪枝。"}, {"name": "$n \\le 500$（三次方级）", "formula": "$O(n^3)$，$10^8$ 次运算上限约 $n \\approx 450$", "note": "Floyd 全源最短路、区间 DP、高斯消元、矩阵快速幂预处理。"}, {"name": "$n \\le 5000$（平方级）", "formula": "$O(n^2)$ 或 $O(n^2 \\log n)$", "note": "二维 DP、树上背包（上下界优化后实为 $O(n^2)$）、枚举点对。"}, {"name": "$n \\le 2 \\times 10^5$（线性对数级）", "formula": "$O(n \\log n)$ 或 $O(n \\log^2 n)$", "note": "线段树、树状数组、二分答案、排序、FFT/NTT、树链剖分。"}, {"name": "$n \\le 10^7$ 与 $n \\le 10^{18}$", "formula": "$O(n)$ 线性筛/双指针；$O(\\log n)$ 或 $O(\\sqrt{n})$", "note": "$10^7$ 禁带 $\\log$ 常数；$10^{18}$ 用矩阵快速幂、数论分块、Pollard-Rho。"}]}, {"heading": "二、数论与组合数学核心公式", "items": [{"name": "扩展欧几里得（ExGCD）", "formula": "$ax + by = \\gcd(a,b)$；通解 $x = x_0 + k\\frac{b}{d},\\ y = y_0 - k\\frac{a}{d}$", "note": "有解充要条件 $\\gcd(a,b) \\mid c$；求最小非负整数解注意先取模再加模。"}, {"name": "费马小定理与欧拉定理", "formula": "$a^{p-1} \\equiv 1 \\pmod p$（$p$ 素数）；$a^{\\varphi(m)} \\equiv 1 \\pmod m$（$\\gcd(a,m)=1$）", "note": "扩展欧拉降幂：$a^b \\equiv a^{b \\bmod \\varphi(m) + \\varphi(m)} \\pmod m$（当 $b \\ge \\varphi(m)$）。"}, {"name": "组合数与卢卡斯（Lucas）定理", "formula": "$\\binom{n}{m} \\equiv \\binom{n \\bmod p}{m \\bmod p} \\binom{\\lfloor n/p \\rfloor}{\\lfloor m/p \\rfloor} \\pmod p$", "note": "适用 $p$ 较小（$p \\le 10^5$）而 $n,m$ 极大；线性逆元预处理 $O(n)$。"}, {"name": "卡特兰数（Catalan）", "formula": "$C_n = \\frac{1}{n+1}\\binom{2n}{n} = \\binom{2n}{n} - \\binom{2n}{n-1}$", "note": "前几项 $1, 1, 2, 5, 14, 42$；对应合法括号序列、二叉树形态、网格不越对角线路径。"}, {"name": "莫比乌斯反演与整除分块", "formula": "$\\sum_{d \\mid n} \\mu(d) = [n=1]$；$\\lfloor \\frac{n}{i} \\rfloor$ 仅 $O(\\sqrt{n})$ 种取值", "note": "整除分块右端点 $r = \\lfloor n / \\lfloor n / l \\rfloor \\rfloor$，常用于 $\\sum \\gcd(i,j)$ 求和。"}]}, {"heading": "三、图论与树上算法复杂度", "items": [{"name": "最短路算法选型", "formula": "Dijkstra $O((V+E)\\log V)$；SPFA 最坏 $O(VE)$；Floyd $O(V^3)$", "note": "非负权必用堆优 Dijkstra（禁 SPFA 防卡）；负环判定用 SPFA 入队超 $n$ 次。"}, {"name": "最小生成树（MST）", "formula": "Kruskal $O(E \\log E)$；Prim $O(V^2)$（稠密图）", "note": "Kruskal 配合并查集路径压缩 + 按秩合并；次小生成树需树上倍增维护边权最大值。"}, {"name": "Tarjan 强连通分量与割点/桥", "formula": "时间 $O(V+E)$；割点 $low[v] \\ge dfn[u]$，桥 $low[v] > dfn[u]$", "note": "无向图求桥注意判父边编号（防重边误判）；缩点后 DAG 上跑拓扑 DP。"}, {"name": "最大流（Dinic）与二分图", "formula": "Dinic 一般图 $O(V^2 E)$，二分图匹配 $O(E\\sqrt{V})$", "note": "当前弧优化 + 多路增广必写；最小割 = 最大流，最大权闭合子图 = 正权和 - 最小割。"}, {"name": "树上倍增 LCA 与树链剖分", "formula": "倍增预处理 $O(n \\log n)$、查询 $O(\\log n)$；重链剖分路径修改 $O(\\log^2 n)$", "note": "树上差分：点差分 $a,b$ 加 $1$，$lca$ 及 $fa[lca]$ 减 $1$；边差分下放至深端点。"}]}, {"heading": "四、数据结构与区间维护", "items": [{"name": "树状数组（BIT）", "formula": "单点改/前缀和 $O(\\log n)$，核心 `x & -x`", "note": "配合差分可实现区间加、区间求和；求逆序对需先离散化。"}, {"name": "线段树与懒标记（Lazy Tag）", "formula": "建树 $O(n)$，区间改查 $O(\\log n)$，空间开 $4n$", "note": "多标记（如先乘后加）注意优先级：`pushdown` 时先乘后加并同步更新加法标记。"}, {"name": "并查集（DSU）", "formula": "路径压缩 + 按秩合并均摊 $O(\\alpha(n))$", "note": "带权并查集在 `find` 递归回溯时更新权值；可撤销并查集禁路径压缩，只能按秩合并。"}, {"name": "ST 表（Sparse Table）", "formula": "预处理 $O(n \\log n)$，静态 RMQ 查询 $O(1)$", "note": "仅支持可重复贡献运算（$\\max, \\min, \\gcd$），区间求和不可用 ST 表。"}, {"name": "单调栈与单调队列", "formula": "均摊 $O(n)$，每元素最多入队/出队一次", "note": "单调栈找左右首个更大/更小元素；单调队列维护定长滑动窗口最值及优化 DP。"}]}, {"heading": "五、字符串与动态规划模型", "items": [{"name": "KMP 与 Z 函数（扩展 KMP）", "formula": "时间 $O(n+m)$；`next[i]` 为最长真前后缀长度", "note": "最小周期判定：若 $n \\bmod (n - next[n]) == 0$ 则周期为 $n - next[n]$。"}, {"name": "AC 自动机与字符串哈希", "formula": "AC 自动机 $O(\\sum |S| + |T|)$；双哈希防冲突", "note": "单哈希模 $10^9+7$ 易被卡，建议双哈希或 `unsigned long long` 自然溢出配随机基数。"}, {"name": "背包 DP 三大变体", "formula": "01 逆序遍历体积；完全正序；多重二进制拆分 $O(V \\sum \\log c_i)$", "note": "求方案数初始化 `dp[0]=1`；求恰好装满最值初始化 `dp[0]=0`，其余 $\\pm\\infty$。"}, {"name": "状态压缩 DP 与子集枚举", "formula": "枚举 $S$ 的所有非空子集：`for(int sub=S; sub; sub=(sub-1)&S)`", "note": "全集子集枚举总复杂度为 $O(3^n)$ 而非 $O(4^n)$。"}, {"name": "数位 DP 与区间 DP", "formula": "数位 DP 记忆化搜索 `dfs(pos, state, limit, lead)`", "note": "区间 DP 外层枚举长度 `len`（从 $2$ 到 $n$），内层枚举左端点 `l`。"}]}, {"heading": "六、计算几何与博弈论", "items": [{"name": "向量点积与叉积", "formula": "$\\vec{a}\\cdot\\vec{b} = x_1x_2+y_1y_2$；$\\vec{a}\\times\\vec{b} = x_1y_2-x_2y_1$", "note": "叉积 $>0$ 表示 $\\vec{b}$ 在 $\\vec{a}$ 逆时针方向；多边形面积 $= \\frac{1}{2}|\\sum P_i \\times P_{i+1}|$。"}, {"name": "二维凸包（Andrew 算法）", "formula": "时间 $O(n \\log n)$，按 $(x, y)$ 升序排序后上下两次单调栈", "note": "判共线点留去：`<= 0` 踢共线点，`< 0` 保留共线点；注意去重重合点。"}, {"name": "Nim 博弈与 SG 函数", "formula": "Nim 先手必胜 $\\iff a_1 \\oplus a_2 \\oplus \\dots \\oplus a_n \\ne 0$", "note": "$SG(x) = \\text{mex}\\{SG(y) \\mid x \\to y\\}$；多独立子游戏和的 $SG$ 等于各子游戏 $SG$ 异或和。"}, {"name": "反 Nim（Anti-Nim）必胜条件", "formula": "所有堆 $=1$ 且异或和 $=0$，或存在堆 $>1$ 且异或和 $\\ne 0$", "note": "最后取完者判负时，不能直接套用普通 Nim 结论。"}]}, {"heading": "七、赛场高频陷阱与调试清单", "items": [{"name": "整型溢出与取模负数", "formula": "`1LL * a * b % mod`；`((a - b) % mod + mod) % mod`", "note": "C++ 负数取模结果为负；位运算 `1LL << k` 必须加 `LL` 后缀防未定义行为。"}, {"name": "多测清空与 memset 陷阱", "formula": "禁对 $10^6$ 数组在多测中反复 `memset`", "note": "$T=10^4$ 次小数据若每次 `memset(1e6)` 会直接 TLE，按实际用到的 `n` 循环清空。"}, {"name": "浮点数精度与 eps", "formula": "比较判等 `fabs(a - b) < 1e-9`；`acos(-1.0)` 求 $\\pi$", "note": "输出 `-0.00` 陷阱：若 `fabs(x) < 1e-9` 强制置 `x = 0`；开方前 `max(0.0, x)`。"}, {"name": "数组越界与无穷大常数", "formula": "`INF = 0x3f3f3f3f`（int）或 `1e18`（long long）", "note": "图论邻接表（链式前向星）无向图边数组必须开 $2M$；`0x3f3f3f3f` 两倍相加不溢出。"}]}]};
